'use strict';

const path = require('node:path');
const yaml = require('js-yaml');
const {parseDefinition} = require('./buildVariables');

/** domains.yaml is generated by sysbuild. Use the declared default image for board-specific evidence. */
function imageDomains(text, root) {
  let data;
  try { data=yaml.load(text,{schema:yaml.FAILSAFE_SCHEMA}); }
  catch { return; }
  if (!Array.isArray(data?.domains) || typeof data.build_dir!=='string' || path.relative(root,data.build_dir)) return;
  const domains=[];
  for (const item of data.domains) {
    if (!item?.name || typeof item.name!=='string' || typeof item.build_dir!=='string' || !path.isAbsolute(item.build_dir)) return;
    const dir=path.normalize(item.build_dir);
    if (!path.relative(root,dir) || domains.some(entry=>entry.name===item.name)) return;
    domains.push({name:item.name,dir});
  }
  const main=domains.find(entry=>entry.name===data.default);
  if (!main) return;
  const order = data.flash_order;
  const validOrder = Array.isArray(order) && new Set(order).size === order.length &&
    order.every(name=>domains.some(domain=>domain.name===name));
  return validOrder ? {main,domains,flashOrder:order} : {main,domains};
}

function configureSource(target, base) {
  return target.system?.cache.get('CMAKE_HOME_DIRECTORY') || (base && path.join(base,'share','sysbuild'));
}

/** A generated tree keeps its original build mode for every later invocation. */
async function buildMode({target, method, preference, westDefault}) {
  const west = method === 'west';
  const selected = target.cacheFile ? Boolean(target.system) : preference;
  const westEnabled = west && selected !== true && /^(true|on|yes|1)$/i.test(await westDefault() || '');
  const enabled = selected ?? westEnabled;
  const westOptions = [];
  if (west && enabled) westOptions.push('--sysbuild');
  // Older Zephyr checkouts have no sysbuild switches. Only override an active west default.
  else if (westEnabled) westOptions.push('--no-sysbuild');
  return {enabled,west,westOptions};
}

function buildLayout(mode, {target, app, cwd, base}, definitions) {
  if (!mode.enabled) return {...mode, source:app, required:[], definitions};

  const source = configureSource(target,base);
  const retained = [];
  let explicitApp;
  for (const argument of definitions) {
    const entry = parseDefinition(argument);
    if (entry?.name === 'APP_DIR') explicitApp = entry.value;
    else retained.push(argument);
  }
  // Both entry points expand APP_DIR in generated CMake code. Backslashes can become CMake escapes.
  const appArgument = '-DAPP_DIR:PATH=' + app.split(path.sep).join('/');
  const appConflict = explicitApp !== undefined && (!explicitApp || Boolean(path.relative(app,path.resolve(cwd,explicitApp))));
  return {...mode, source:source || '<ZEPHYR_BASE>/share/sysbuild', required:[appArgument],
    definitions:retained, appConflict, issue:!mode.west && !source ? 'systemSource' : undefined};
}

module.exports={imageDomains,configureSource,buildMode,buildLayout};
